/* @lc app=leetcode id=2092 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun findAllPeople(n: Int, meetings: Array<IntArray>, firstPerson: Int): List<Int> = IntArray(n) { it }.also { p -> p[firstPerson] = 0 }.also { p -> meetings.sortedBy { it[2] }.groupBy { it[2] }.values.forEach { g -> g.forEach { (a, b, _) -> p[find(p, a)] = find(p, b) }.let { g.flatMap { listOf(it[0], it[1]) }.distinct().filter { find(p, it) != find(p, 0) }.forEach { p[it] = it } } } }.let { p -> (0 until n).filter { find(p, it) == find(p, 0) } } }